const QRCode = require('qrcode')


export const makeQrCode = {
    data() {
        return {
            domId: 'canvas-qr-code',
            shareUrl: '',
            cover: ''
        }
    },
    methods: {
        makeQrCode() {
            const img = new Image()
            img.src = this.cover
            const canvas = document.getElementById(this.domId)
            const ctx = canvas.getContext('2d')
            const dataToEncode = this.shareUrl
            QRCode.toCanvas(
                canvas,
                dataToEncode, {
                    width: 180,
                    height: 180,
                },
                function (error) {
                    if (error) console.error(error)
                    img.width = 35
                    img.height = (img.width * canvas.height) / canvas.width
                    img.onload = function () {
                        const centerX = (canvas.width - img.width) / 2
                        const centerY = (canvas.height - img.height) / 2
                        // 创建遮罩
                        ctx.fillStyle = 'rgba(0, 0, 0, 0)' // 白色遮罩（或者使用 'rgba(0, 0, 0, 0)' 来设置透明）
                        ctx.fillRect(centerX, centerY, img.width, img.height) // 在图片位置创建遮罩
                        ctx.drawImage(img, centerX, centerY, img.width, img.height) // 自定义图片在二维码上的位置和尺寸
                    }
                }
            )
        }
    }
}