<template>
    <el-dialog
    title="二维码分享"
    :visible.sync="visible"
    width="240px"
    :center="true"
  >
    <canvas :id="domId"></canvas>
  </el-dialog>
</template>
<script>
import { makeQrCode } from '@/mixins/MakeQrCode'
import { getShareUrl } from '@/api/vr'
export default {
  name: 'ShareVrQRCode',
  mixins: [makeQrCode],
  data() {
    return {
        domId: 'vr-share-vr-qr-code',
        visible: false
    }
  },
  methods: {
    async open(productId) {
      const {url, cover} = await getShareUrl(productId)
      this.shareUrl = url
      this.cover = cover
      this.visible = true
      this.$nextTick(() => {
        this.makeQrCode()
      })
    }
  }
}
</script>